import 'package:mad_flutter_practicum/app/app.dart';
import 'package:mad_flutter_practicum/domain/domain.dart';

import 'widgets/widgets.dart';

class CurrencyListPage extends StatefulWidget {
  const CurrencyListPage({super.key});

  @override
  State<CurrencyListPage> createState() => _CurrencyListPageState();
}

class _CurrencyListPageState extends State<CurrencyListPage>
    with SingleTickerProviderStateMixin, WidgetsBindingObserver {
  late final AnimationController _fadeController;

  List<CurrencyModel> _allCurrencies = [];

  int _currentPage = 0;
  bool _hasMore = true;
  bool _isLoadingMore = false;
  bool _isLoaded = false;

  @override
  void initState() {
    super.initState();
    WidgetsBinding.instance.addObserver(this);
    _initAnimation();
    _loadInitialPage();
  }

  @override
  void dispose() {
    WidgetsBinding.instance.removeObserver(this);
    _fadeController.dispose();
    super.dispose();
  }

  @override
  void didChangeAppLifecycleState(AppLifecycleState state) {
    if (state == AppLifecycleState.resumed && _isLoaded) {
      // При возврате экрана — свежий запрос с base: 'USD'
      _resetAndReload();
    }
  }

  void _initAnimation() {
    _fadeController = AnimationController(
      duration: const Duration(milliseconds: 400),
      vsync: this,
    );
  }

  Future<void> _loadInitialPage() async {
    final currencyRepository = context.read<CurrencyRepository>();
    _currentPage = 0;
    _allCurrencies.clear();
    _hasMore = true;

    try {
      final CurrencyPage page = await currencyRepository.fetchRates(
        const CurrencyPageRequest(base: 'USD'),
      );
      _allCurrencies.addAll(page.items);
      _currentPage = 1;
      _hasMore = page.hasMore;

      if (_hasMore) {
        // подгружаем ещё страницу, чтобы список был полнее сразу
        await _loadNextPage(currencyRepository);
      }

      _isLoaded = true;
      _fadeController.forward();
    } catch (e) {
      debugPrint('Error loading currency list: $e');
    }
  }

  Future<void> _resetAndReload() async {
    final currencyRepository = context.read<CurrencyRepository>();
    setState(() {
      _allCurrencies.clear();
      _currentPage = 0;
      _hasMore = true;
      _isLoadingMore = false;
    });

    try {
      final CurrencyPage page = await currencyRepository.fetchRates(
        const CurrencyPageRequest(base: 'USD'),
      );
      setState(() {
        _allCurrencies.addAll(page.items);
        _currentPage = 1;
        _hasMore = page.hasMore;
        _isLoaded = true;
      });

      if (_hasMore) {
        await _loadNextPage(currencyRepository);
      }
    } catch (e) {
      debugPrint('Error reloading currency list: $e');
    }
  }

  Future<void> _loadNextPage(CurrencyRepository repository) async {
    setState(() => _isLoadingMore = true);

    try {
      final CurrencyPage page = await repository.fetchRates(
        CurrencyPageRequest(base: 'USD', page: _currentPage),
      );
      setState(() {
        _allCurrencies.addAll(page.items);
        _currentPage++;
        _hasMore = page.hasMore;
      });

      if (_hasMore) {
        await _loadNextPage(repository);
      } else {
        // Сохраняем результат в БД
        repository.saveCurrencyList(_allCurrencies);
      }
    } catch (e) {
      debugPrint('Error loading more currencies: $e');
    } finally {
      setState(() => _isLoadingMore = false);
    }
  }

  void _filterCurrencies(String query) {
    // Фильтрация пока не используется с пагинацией — это упрощённая версия
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(title: Text(context.loc.currencyRate)),
      body: _isLoaded && _allCurrencies.isEmpty
          ? const Center(child: Text('No data'))
          : Column(
              children: [
                Padding(
                  padding:
                      const EdgeInsets.symmetric(vertical: 10, horizontal: 22),
                  child: SearchView(onChanged: _filterCurrencies),
                ),
                Expanded(
                  child: FadeTransition(
                    opacity: _fadeController.view,
                    child: ListView.builder(
                      itemCount: _allCurrencies.length + (_hasMore ? 1 : 0),
                      itemBuilder: (BuildContext context, int index) {
                        if (index >= _allCurrencies.length) {
                          return Padding(
                            padding: const EdgeInsets.all(20.0),
                            child: Column(
                              children: [
                                ElevatedButton(
                                  onPressed: (_isLoadingMore || !_hasMore)
                                      ? null
                                      : () => _loadNextPage(
                                            context.read<CurrencyRepository>()),
                                  child: Text(context.loc.showMore),
                                ),
                                if (_isLoadingMore)
                                  const Padding(
                                    padding: EdgeInsets.only(top: 8.0),
                                    child: SizedBox(
                                      height: 20,
                                      width: 20,
                                      child: CircularProgressIndicator(
                                        strokeWidth: 2,
                                      ),
                                    ),
                                  ),
                              ],
                            ),
                          );
                        }

                        final CurrencyModel currency = _allCurrencies[index];
                        return Padding(
                          key: ValueKey(currency.id),
                          padding: index == 0
                              ? const EdgeInsets.only(top: 20)
                              : const EdgeInsets.only(top: 10),
                          child: CurrencyCard(model: currency),
                        );
                      },
                      padding: const EdgeInsets.fromLTRB(22, 0, 22, 40),
                    ),
                  ),
                ),
              ],
            ),
    );
  }
}
